    DAILY_SALARY = 70
    day = int(day_context['day'])
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append((oid, opp))

    if not alive_opps:
        if hp <= 3 or no_water >= 1:
            return float(min(budget, 45.0))
        return float(min(budget, 18.0))

    prev_bids = []
    rich_aggressive = 0
    desperate_opps = 0
    for oid, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('budget', 0) >= 300:
            rich_aggressive += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_opps += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17.0
    medium_supply = supply <= 20.0
    danger = (hp <= 3) or (no_water >= 1)
    severe_danger = (hp <= 2) or (no_water >= 2)

    if severe_danger:
        bid = max(95.0, highest_prev + 3.0)
        return float(min(budget, bid))

    if danger:
        if tight_supply:
            bid = max(88.0, highest_prev + 2.0)
        else:
            bid = max(72.0, avg_prev * 0.72)
        return float(min(budget, bid))

    if tight_supply:
        if highest_prev >= 120.0:
            bid = 34.0
        else:
            bid = max(62.0, highest_prev * 0.62)
    elif medium_supply:
        if rich_aggressive >= 2 and highest_prev >= 105.0:
            bid = 26.0
        else:
            bid = max(38.0, avg_prev * 0.42)
    else:
        bid = 16.0

    if desperate_opps >= 2 and not tight_supply:
        bid = min(bid, 22.0)

    if day >= 8 and budget > 180 and hp >= 5 and medium_supply:
        bid = max(bid, 52.0)

    if budget < 80:
        bid = min(bid, max(12.0, budget * 0.55))

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 80.0

    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], DAILY_SALARY * 1.3)
    elif my_status['hp'] >= 8:
        bid = min(my_status['budget'], DAILY_SALARY * 0.7)
    else:
        bid = min(my_status['budget'], max(avg_prev * 1.05, DAILY_SALARY * 0.9))

    return float(bid)
